package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Audit-only: measure the actual settled window and coordinate independent Craft screenshots. */
public class CraftUiAudit extends Instrumentation {
 LauncherActivity a;int cases;final ArrayList<String> issues=new ArrayList<>();
 void ui(Runnable r){Throwable[] fail={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){fail[0]=t;}});waitForIdleSync();if(fail[0]!=null)throw new AssertionError(fail[0]);}
 void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(cmd);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] buf=new byte[1024];while(in.read(buf)>0){}}}
 JSONObject bounds(View v)throws Exception{int[] xy=new int[2];v.getLocationOnScreen(xy);return new JSONObject().put("x",xy[0]).put("y",xy[1]).put("width",v.getWidth()).put("height",v.getHeight());}
 View find(View v,String name){if(name.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View hit=find(((ViewGroup)v).getChildAt(i),name);if(hit!=null)return hit;}return null;}
 void scan(View v,JSONArray text,JSONArray controls)throws Exception{
  if(v.getVisibility()!=View.VISIBLE)return;Rect visible=new Rect();if(v.getWidth()<=0||v.getHeight()<=0||!v.getGlobalVisibleRect(visible))return;
  if(v instanceof TextView){TextView t=(TextView)v;String value=t.getText().toString();android.text.Layout l=t.getLayout();if(!value.isEmpty()&&l!=null){float available=t.getWidth()-t.getCompoundPaddingLeft()-t.getCompoundPaddingRight(),h=t.getHeight()-t.getExtendedPaddingTop()-t.getExtendedPaddingBottom();boolean clip=false;for(int i=0;i<l.getLineCount();i++)if(l.getEllipsisCount(i)==0&&l.getLineWidth(i)>available+2)clip=true;if(l.getLineCount()>0&&l.getLineBottom(l.getLineCount()-1)>h+2)clip=true;JSONObject item=bounds(t).put("text",value).put("sp",t.getTextSize()/t.getResources().getDisplayMetrics().scaledDensity).put("clipped",clip).put("ellipsized",l.getLineCount()>0&&l.getEllipsisCount(l.getLineCount()-1)>0);text.put(item);if(clip)issues.add("text: "+value);}}
  if(v.getContentDescription()!=null)controls.put(bounds(v).put("description",v.getContentDescription()));
  if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)scan(((ViewGroup)v).getChildAt(i),text,controls);
 }
 void write(String name,String value)throws Exception{try(FileOutputStream f=new FileOutputStream(new File(a.getFilesDir(),name))){f.write(value.getBytes("UTF-8"));}if(name.endsWith(".json")){try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){f.write(value.getBytes("UTF-8"));}}}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;android.content.SharedPreferences p=getTargetContext().getSharedPreferences("idash",0);Map<String,?> saved=new HashMap<>(p.getAll());try{
 p.edit().putBoolean("motion",false).putBoolean("calendar",true).putBoolean("jakim",true).putInt("dock_size",0).putString("jakim_zone","SGR02").putInt("panel_mode",1).putBoolean("fm_premium",true).apply();a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(2);a.worker.execute(()->a.main.post(ready::countDown));a.networkWorker.execute(()->a.main.post(ready::countDown));if(!ready.await(45,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("data ready timeout");
 for(String size:new String[]{"1024x600","800x480"}){shell("wm size "+size);waitForIdleSync();for(boolean panel:new boolean[]{false,true}){
  String id=(panel?"fm-":"home-")+size;ui(()->{a.page="home";a.panelVisible=panel;a.render();});SystemClock.sleep(1000);waitForIdleSync();for(int focus=0;focus<100&&!a.hasWindowFocus();focus++)SystemClock.sleep(100);if(!a.hasWindowFocus())throw new AssertionError("Window occluded; native capture invalid: "+id);JSONObject[] result={null};ui(()->{try{JSONArray text=new JSONArray(),controls=new JSONArray();scan(a.stage,text,controls);View clock=find(a.stage,"Clock widget"),prayer=find(a.stage,"JAKIM calendar widget"),dock=find(a.stage,"Launcher dock");JSONObject r=new JSONObject().put("window_focused",a.hasWindowFocus()).put("case",id).put("viewport",bounds(a.stage)).put("clock",bounds(clock)).put("prayer",bounds(prayer)).put("dock",bounds(dock)).put("text",text).put("controls",controls).put("card_equal",clock.getWidth()==prayer.getWidth()&&clock.getHeight()==prayer.getHeight()).put("card_gap",prayer.getTop()-clock.getBottom());if(panel)r.put("fm",bounds(a.fmPanel)).put("panel",bounds(a.panelBox));result[0]=r;}catch(Exception e){throw new AssertionError(e);}});
  write("craft-"+id+".json",result[0].toString(2));File next=new File(a.getFilesDir(),"craft-next-"+id);next.delete();write("craft-ready",id);long deadline=SystemClock.uptimeMillis()+90000;while(!next.exists()&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(100);if(!next.exists())throw new AssertionError("capture coordinator timeout: "+id);cases++;
 }}
 out.putString("stream","PASS: "+cases+" settled native UI cases; measured text candidates="+issues.size()+"\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL: "+t+"\n");}finally{try{shell("wm size 1024x600");}catch(Exception ignored){}if(a!=null)ui(a::finish);AppearanceChecks.restore(p,saved);}finish(code,out);}
}
